+    public ByteSizeValue getSize() {
+        return size;
+    }
+
+    /**
+     * @return the number of segments in this shard snapshot
+     */
+    public int getSegmentCount() {
+        return segmentCount;
+    }
+
+    @Override
+    public void writeTo(StreamOutput out) throws IOException {
+        out.writeString(generation);
